create or replace function public.request_cut_file_generation(p_cut_id uuid,p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public,app_private,pg_temp as $$
declare v_actor uuid:=app_private.require_active_actor();v_cut public.inventory_cuts%rowtype;v_file public.generated_files%rowtype;
begin if p_request_id is null then raise exception 'Generation request_id is required' using errcode='23514';end if;select * into v_cut from public.inventory_cuts where id=p_cut_id;if not found then raise exception 'Cut not found' using errcode='P0002';end if;perform app_private.lock_inventory(v_cut.inventory_id);select * into v_cut from public.inventory_cuts where id=p_cut_id for update;if not app_private.can_manage_inventory(v_cut.inventory_id) then raise exception 'Not authorized to generate cut file' using errcode='42501';end if;select * into v_file from public.generated_files where cut_id=p_cut_id and file_type='CUT_XLSX';if v_cut.status='READY' then return jsonb_build_object('action','READY','cut_id',p_cut_id,'request_id',v_cut.generation_request_id);end if;if found then return jsonb_build_object('action','RECOVER','cut_id',p_cut_id,'request_id',v_cut.generation_request_id);end if;if v_cut.status='SNAPSHOT_CREATED' and v_cut.generation_request_id is not null then if v_cut.generation_request_id=p_request_id then return jsonb_build_object('action','GENERATE','cut_id',p_cut_id,'request_id',p_request_id);end if;raise exception 'Generation already in progress' using errcode='55P03';end if;if v_cut.status not in('SNAPSHOT_CREATED','ERROR') then raise exception 'Cut is not ready for file generation' using errcode='23514';end if;update public.inventory_cuts set status='SNAPSHOT_CREATED',generation_request_id=p_request_id,generation_claimed_at=now(),generation_requested_by=v_actor,generation_error=null where id=p_cut_id;return jsonb_build_object('action','GENERATE','cut_id',p_cut_id,'request_id',p_request_id);end $$;
